Subject: [PATCH] applets/kicker: Give System Settings search results a context
 menu

Only the services runner's results were turned into a service, so KCM
results had no menu or favorite id. Look the service up for both runners
and use it for the menu, the favorite id and the triggered actions.

BUG: 519038
---
 applets/kicker/runnermatchesmodel.cpp | 53 ++++++++++++++-------------
 1 file changed, 27 insertions(+), 26 deletions(-)

diff --git a/applets/kicker/runnermatchesmodel.cpp b/applets/kicker/runnermatchesmodel.cpp
index 8c1ea5790c..7a69b87bcc 100644
--- a/applets/kicker/runnermatchesmodel.cpp
+++ b/applets/kicker/runnermatchesmodel.cpp
@@ -24,6 +24,24 @@
 #include <KSharedConfig>
 #include <Plasma/Plasma>

+// The application or KCM behind a match. Only the services and systemsettings runners are
+// asked: assuming that any other runner returns something we want to turn into a KService is
+// unsafe, e.g. files from the Baloo runner might match a storageId just by accident,
+// creating a dangerous false positive.
+static KService::Ptr serviceForMatch(const KRunner::QueryMatch &match)
+{
+    const QString runnerId = match.runner()->id();
+    if (runnerId == QLatin1String("krunner_services")) {
+        const QUrl url = match.data().toUrl();
+        return url.scheme() == QLatin1String("applications") ? KService::serviceByStorageId(url.path()) : KService::Ptr();
+    }
+    if (runnerId == QLatin1String("krunner_systemsettings") && !match.urls().isEmpty()) {
+        // the KCM's .desktop file
+        return KService::serviceByStorageId(match.urls().constFirst().toLocalFile());
+    }
+    return {};
+}
+
 RunnerMatchesModel::RunnerMatchesModel(const QString &runnerId, const std::optional<QString> &name, QObject *parent)
     : KRunner::ResultsModel(KSharedConfig::openConfig(QStringLiteral("krunnerrc"))->group(QStringLiteral("Plugins")),
                             KSharedConfig::openStateConfig()->group(QStringLiteral("KickerRunnerManager")),
@@ -97,6 +115,9 @@ QVariant RunnerMatchesModel::data(const QModelIndex &index, int role) const
         if (match.runner()->id() == QLatin1String("krunner_services")) {
             return match.data().toString();
         }
+        if (const KService::Ptr service = serviceForMatch(match)) {
+            return QString(QStringLiteral("applications:") + service->storageId());
+        }
     } else if (role == Kicker::UrlRole) {
         const QList<QUrl> urls = match.urls();
         if (urls.isEmpty()) {
@@ -125,7 +146,7 @@ QVariant RunnerMatchesModel::data(const QModelIndex &index, int role) const
         }
         return QUrl::fromLocalFile(path);
     } else if (role == Kicker::HasActionListRole) {
-        return match.runner()->id() == QLatin1String("krunner_services") || !match.runner()->findChildren<QAction *>().isEmpty();
+        return match.runner()->id() == QLatin1String("krunner_services") || !match.runner()->findChildren<QAction *>().isEmpty() || serviceForMatch(match);
     } else if (role == Kicker::IsMultilineTextRole) {
         return match.isMultiLine();
     } else if (role == Kicker::ActionListRole) {
@@ -140,30 +161,13 @@ QVariant RunnerMatchesModel::data(const QModelIndex &index, int role) const
             actionList << item;
         }

-        // Only try to get a KService for matches from the services and systemsettings runner. Assuming
-        // that any other runner returns something we want to turn into a KService is
-        // unsafe, e.g. files from the Baloo runner might match a storageId just by
-        // accident, creating a dangerous false positive.
-        if (match.runner()->id() != QLatin1String("krunner_services") && match.runner()->id() != QLatin1String("krunner_systemsettings")) {
-            return actionList;
-        }
-
-        QUrl dataUrl(match.data().toUrl());
-        if (dataUrl.isEmpty() && !match.urls().isEmpty()) {
-            // needed for systemsettigs runner
-            dataUrl = match.urls().constFirst();
-        }
-        if (dataUrl.scheme() != QLatin1String("applications")) {
-            return actionList;
-        }
-
         // Don't offer jump list actions on a jump list action.
-        const QString actionName = QUrlQuery(dataUrl).queryItemValue(QStringLiteral("action"));
+        const QString actionName = QUrlQuery(match.data().toUrl()).queryItemValue(QStringLiteral("action"));
         if (!actionName.isEmpty()) {
             return actionList;
         }

-        const KService::Ptr service = KService::serviceByStorageId(dataUrl.path());
+        const KService::Ptr service = serviceForMatch(match);
         if (service) {
             if (!actionList.isEmpty()) {
                 actionList << Kicker::createSeparatorActionItem();
@@ -209,7 +213,8 @@ QVariant RunnerMatchesModel::data(const QModelIndex &index, int role) const
                 return actionList;
             }

-            if (service->isApplication()) {
+            // KCMs are not in the menu editor or the software center
+            if (service->isApplication() && match.runner()->id() == QLatin1String("krunner_services")) {
                 actionList << Kicker::editApplicationAction(service);
                 actionList << Kicker::appstreamActions(service);
             }
@@ -245,11 +250,7 @@ bool RunnerMatchesModel::trigger(int row, const QString &actionId, const QVarian

     QObject *appletInterface = static_cast<RunnerModel *>(parent())->appletInterface();

-    KService::Ptr service = KService::serviceByStorageId(match.data().toUrl().toString(QUrl::RemoveScheme));
-    if (!service && !match.urls().isEmpty()) {
-        // needed for systemsettigs runner
-        service = KService::serviceByStorageId(match.urls().constFirst().toString(QUrl::RemoveScheme));
-    }
+    const KService::Ptr service = serviceForMatch(match);

     if (Kicker::handleAddLauncherAction(actionId, appletInterface, service)) {
         return false; // We don't want to close Kicker, BUG: 390585
